/* Mindful Space frontend — talks to the Flask API (/api/*) */
const $=(s,e=document)=>e.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const inr=n=>'₹'+Number(n).toLocaleString('en-IN');
const app=$('#app');
let ME=null,META=null,POLL=null;
const U={view:'home',q:'',city:'',spec:'',sort:'near',maxFee:3000,mode:'',tab:'counsellors',peer:null,lastId:0,hq:''};
const V={};
const TITLES=['Clinical Psychologist','Counselling Psychologist','Psychiatrist','Psychotherapist','Child & Adolescent Counsellor','Couples & Family Therapist','Rehabilitation Psychologist','Counsellor'];
const CONCERNS=['Anxiety','Low mood','Stress','Sleep','Relationships','Work / studies','Grief','Self-esteem','Anger','Trauma','Habits & addiction','Just exploring'];
const PRACT=[['breathing','🌬','Breathe','Slow 4-6 breathing'],['grounding','🪨','Ground','5-4-3-2-1 senses'],['gratitude','🌼','Gratitude','Write 3 good things'],['stretch','🧘','Stretch','4 gentle moves'],['sound','🌧','Calm sound','Soft rain-like noise']];

/* ---------- utils ---------- */
async function api(path,method='GET',body){
  const o={method,credentials:'same-origin',headers:{}};
  if(method!=='GET'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(body||{})}
  let r;try{r=await fetch('/api'+path,o)}catch(e){throw new Error('Cannot reach the server. Check your connection.')}
  let j={};try{j=await r.json()}catch(e){}
  if(r.status===401&&ME){ME=null;renderAuth();throw new Error('Please sign in again.')}
  if(!r.ok)throw new Error(j.error||'Something went wrong.');return j}
function toast(m){const t=document.createElement('div');t.className='toast';t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),3400)}
const run=fn=>async(...a)=>{try{await fn(...a)}catch(e){toast(e.message)}};
function hue(s){let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))%360;return h}
function av(name,cls=''){const ini=String(name).replace(/^Dr\.?\s*/,'').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();const h=hue(name);return `<div class="avatar ${cls}" style="background:linear-gradient(135deg,hsl(${h} 55% 45%),hsl(${(h+50)%360} 60% 55%))">${esc(ini)}</div>`}
const fmtDate=(d,t)=>{const x=new Date(d+'T'+(t||'00:00')+':00');return x.toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})+(t?', '+x.toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}):'')};
const isoDay=off=>{const d=new Date(Date.now()+off*864e5+330*6e4);return d.toISOString().slice(0,10)};
function km(a,b,c,d){const r=x=>x*Math.PI/180,dl=r(c-a),dn=r(d-b);const x=Math.sin(dl/2)**2+Math.cos(r(a))*Math.cos(r(c))*Math.sin(dn/2)**2;return 2*6371*Math.asin(Math.sqrt(x))}
(function theme(){try{const t=localStorage.getItem('ms_theme');if(t)document.documentElement.dataset.theme=t}catch(e){}})();
function crisisModal(){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="card"><h3>You don't have to carry this alone</h3><p class="muted" style="margin:8px 0 14px">It sounds like things may be very heavy right now. Please talk to someone — it's free and confidential.</p><div style="display:grid;gap:8px">${META.helplines.filter(h=>['14416','18005990019','112'].includes(h.phone)).map(h=>`<a class="btn rose" href="tel:${h.phone}">📞 ${esc(h.name)} — ${esc(h.alt)}</a>`).join('')}</div><button class="btn ghost" style="width:100%;margin-top:12px" data-x>Close</button></div>`;m.querySelector('[data-x]').onclick=()=>m.remove();document.body.appendChild(m)}

/* ---------- AUTH ---------- */
let W={role:'user',step:0,phone:'',otpIn:'',dev:null,resendAt:0,d:{},err:'',busy:false};
const steps=()=>W.role==='user'?['phone','otp','u1','u2','u3']:['phone','otp','c1','c2','c3'];
function renderAuth(){
  const st=steps()[W.step];const prog=steps().map((_,i)=>`<i class="${i<=W.step?'on':''}"></i>`).join('');
  app.innerHTML=`<div class="auth"><section class="hero"><div class="orb" style="width:340px;height:340px;right:-90px;top:-80px"></div><div class="orb" style="width:180px;height:180px;left:40%;bottom:60px"></div>
<div class="logo"><i>◐</i>Mindful Space</div>
<div style="position:relative"><h1>Feel heard.<br>Find someone near you.</h1><p style="margin-top:16px;max-width:460px;opacity:.9;font-size:17px">Counsellors across India, daily wellbeing practices and a kind community — priced in rupees, in your language.</p>
<ul><li>📍<div><b>Counsellors near you</b>Search any city from Delhi to Thiruvananthapuram</div></li><li>🔒<div><b>Private by design</b>Use a nickname with friends and the community</div></li><li>🪪<div><b>ID-reviewed professionals</b>Counsellors register with their council number</div></li></ul></div>
<p class="small" style="opacity:.85;position:relative">In crisis? Call Tele-MANAS 14416 (free, 24×7) or 112.</p></section>
<section class="panel"><div class="card"><div class="steps">${prog}</div>${authStep(st)}</div></section></div>`;bindAuth()}
function chips(k,list,single){const sel=W.d[k]||(single?'':[]);return list.map(v=>{const on=single?sel===v:sel.includes(v);return `<button type="button" class="chip ${on?'on':''}" data-act="chip" data-k="${k}" data-v="${esc(v)}" data-single="${single?1:0}">${esc(v)}</button>`}).join('')}
function fld(k,label,type='text',ph='',extra=''){return `<label class="f" for="f_${k}">${label}</label><input class="in" id="f_${k}" data-bind="${k}" type="${type}" placeholder="${ph}" value="${esc(W.d[k]||'')}" ${extra}>`}
function sel(k,label,opts){return `<label class="f" for="f_${k}">${label}</label><select class="in" id="f_${k}" data-bind="${k}">${['',...opts].map(g=>`<option ${W.d[k]===g?'selected':''} value="${esc(g)}">${esc(g||'Select')}</option>`).join('')}</select>`}
function cityOptions(s){return `<option value="">Choose your city</option>`+META.cities.slice().sort((a,b)=>a[0].localeCompare(b[0])).map(c=>`<option ${s===c[0]?'selected':''} value="${c[0]}">${c[0]}, ${c[1]}</option>`).join('')}
function authStep(st){const e=`<div class="err" id="err" role="alert">${esc(W.err)}</div>`,B=W.busy?'disabled':'';
if(st==='phone')return `<div class="seg"><button class="${W.role==='user'?'on':''}" data-act="role" data-v="user">I need support</button><button class="${W.role==='counsellor'?'on':''}" data-act="role" data-v="counsellor">I'm a counsellor</button></div>
<h2 style="margin-top:18px">${W.role==='user'?'Welcome 👋':'Counsellor sign-in'}</h2><p class="muted" style="margin-top:6px">${W.role==='user'?'Enter your mobile number. We will text you a 6-digit code.':'Sign in or register with your mobile number. You will add your council registration ID in the next steps.'}</p>
<label class="f" for="f_phone">Mobile number</label><div class="row"><span class="in" style="width:70px;text-align:center;flex:none">+91</span><input class="in" id="f_phone" data-bind="phone" inputmode="numeric" maxlength="10" placeholder="98765 43210" value="${esc(W.phone)}" autocomplete="tel-national"></div>${e}
<button class="btn" style="width:100%;margin-top:10px" data-act="sendotp" ${B}>Send code</button><p class="small muted" style="margin-top:14px">By continuing you agree to our Terms and Privacy Policy.</p>`;
if(st==='otp')return `<h2>Verify your number</h2><p class="muted" style="margin-top:6px">We sent a code to +91 ${esc(W.phone.slice(0,2))}••••••${esc(W.phone.slice(-2))}. It expires in 5 minutes.</p>
${W.dev?`<div class="sms"><b>Development mode</b><br>Code: <b style="font-size:18px">${esc(W.dev)}</b><div style="opacity:.7;margin-top:4px">Shown because no SMS provider is configured on this server (DEV_SHOW_OTP=1).</div></div>`:''}
<label class="f" for="f_otp">Enter code</label><input class="in otp" id="f_otp" data-bind="otpIn" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="••••••" value="${esc(W.otpIn||'')}">${e}
<button class="btn" style="width:100%;margin-top:10px" data-act="verify" ${B}>Verify and continue</button>
<div class="row between" style="margin-top:14px"><button class="btn ghost sm" data-act="back">Change number</button><button class="btn ghost sm" id="rs" data-act="resend">Resend code</button></div>`;
if(st==='u1')return `<h2>About you</h2><p class="muted" style="margin-top:6px">This helps us personalise your space. Only you can see these details.</p>
${fld('name','Full name','text','Your name')}${fld('nick','Nickname for friends & community','text','e.g. QuietRiver')}
<div class="row" style="gap:12px"><div class="grow">${fld('age','Age','number','18','min="13" max="99"')}</div><div class="grow">${sel('gender','Gender',['Woman','Man','Non-binary','Prefer not to say'])}</div></div>${e}
<button class="btn" style="width:100%;margin-top:10px" data-act="next">Continue</button>`;
if(st==='u2'||st==='c2')return `<h2>${st==='u2'?'Where are you?':'Your practice'}</h2><p class="muted" style="margin-top:6px">${st==='u2'?'We use your location to show counsellors nearby. You can change it any time.':'Clients find you by location, so pick your city and locality.'}</p>
<button class="btn teal" style="width:100%;margin-top:14px" data-act="locate">📍 Use my current location</button><div class="small muted" style="margin-top:8px">${W.d.lat?'Location saved — nearest city: '+esc(W.d.city):''}</div>
<label class="f" for="f_city">${W.d.lat?'City (nearest match)':'Or choose your city'}</label><select class="in" id="f_city" data-bind="city">${cityOptions(W.d.city)}</select>
${st==='c2'?fld('area','Clinic / locality','text','e.g. Civil Lines')+fld('exp','Years of experience','number','5','min="0" max="60"')+`<label class="f">Specialisations (up to 4)</label>${chips('spec',META.specs)}<label class="f">Session modes</label>${chips('modes',['Video','Audio','In-person'])}`:''}
<label class="f">${st==='u2'?'Languages you are comfortable in':'Languages you counsel in'}</label>${chips('langs',META.langs)}${e}
<div class="row"><button class="btn ghost" data-act="back">Back</button><button class="btn grow" data-act="next">Continue</button></div>`;
if(st==='u3')return `<h2>What brings you here?</h2><label class="f">Choose what fits (pick any)</label>${chips('concerns',CONCERNS)}
<label class="f">Preferred session type</label>${chips('mode_pref',['Video','Audio','Chat','In-person'],true)}
${fld('em_name','Emergency contact name (optional)','text','Someone you trust')}${fld('em_phone','Emergency contact number (optional)','tel','10-digit number','maxlength="10"')}
<label class="row small" style="margin-top:16px;align-items:flex-start"><input type="checkbox" data-bind="consent" ${W.d.consent?'checked':''} style="margin-top:3px"><span>I understand Mindful Space supports wellbeing and does not replace emergency or medical care.</span></label>${e}
<div class="row" style="margin-top:12px"><button class="btn ghost" data-act="back">Back</button><button class="btn grow" data-act="finish" ${B}>Create my space</button></div>`;
if(st==='c1')return `<h2>Professional ID</h2><p class="muted" style="margin-top:6px">Counsellors register with a council ID. Your profile appears in search after our team verifies it.</p>
${fld('name','Full name (as on certificate)','text','Dr. / Ms. / Mr.')}${fld('email','Email','email','you@clinic.in')}${sel('title','Professional title',TITLES)}${sel('council','Registering body',META.councils)}
${fld('reg_id','Registration / CRR number','text','e.g. A12345 or CRR/2019/04567')}${fld('qual','Highest qualification','text','e.g. M.Phil Clinical Psychology')}${e}
<div class="row" style="margin-top:12px"><button class="btn ghost" data-act="back">Back</button><button class="btn grow" data-act="next">Continue</button></div>`;
if(st==='c3')return `<h2>Fees & profile</h2>${fld('fee','Fee per 50-minute session (₹)','number','1000','min="200" max="10000" step="50"')}
<label class="f" for="f_bio">Short bio</label><textarea class="in" id="f_bio" data-bind="bio" placeholder="How do you work with clients?">${esc(W.d.bio||'')}</textarea>
${fld('contact_phone','Public contact number (optional)','tel','10-digit number','maxlength="10"')}
<label class="row small" style="margin-top:10px;align-items:flex-start"><input type="checkbox" data-bind="show_contact" ${W.d.show_contact?'checked':''} style="margin-top:3px"><span>Show my phone and email to clients so they can contact me directly.</span></label>
<label class="row small" style="margin-top:10px;align-items:flex-start"><input type="checkbox" data-bind="consent" ${W.d.consent?'checked':''} style="margin-top:3px"><span>I confirm my registration details are accurate and I will follow professional ethics and confidentiality.</span></label>${e}
<div class="row" style="margin-top:12px"><button class="btn ghost" data-act="back">Back</button><button class="btn grow" data-act="finish" ${B}>Submit for verification</button></div>`}
function bindAuth(){document.querySelectorAll('[data-bind]').forEach(el=>{const h=()=>{const k=el.dataset.bind;const v=el.type==='checkbox'?el.checked:el.value;if(k==='phone')W.phone=v.replace(/\D/g,'');else if(k==='otpIn')W.otpIn=v.replace(/\D/g,'');else W.d[k]=v};el.addEventListener('input',h);el.addEventListener('change',h)});
  if(steps()[W.step]==='otp')resendTimer()}
function resendTimer(){clearInterval(W.rt);const t=()=>{const b=$('#rs');if(!b){clearInterval(W.rt);return}const l=Math.max(0,Math.ceil((W.resendAt-Date.now())/1000));b.disabled=l>0;b.textContent=l>0?`Resend in ${l}s`:'Resend code'};t();W.rt=setInterval(t,500)}
function aerr(m){W.err=m;const e=$('#err');if(e)e.textContent=m}
function validateStep(){const st=steps()[W.step],d=W.d;
  if(st==='u1'){if(!(d.name||'').trim())return'Please enter your name.';if((d.nick||'').trim().length<3)return'Choose a nickname of at least 3 characters.';const a=+d.age;if(!a||a<13||a>99)return'Enter a valid age (13 or above).';if(!d.gender)return'Please select an option for gender.'}
  if(st==='u2'||st==='c2'){if(!d.city)return'Choose your city or use your location.';if(!(d.langs||[]).length)return'Pick at least one language.'}
  if(st==='c1'){if(!(d.name||'').trim())return'Enter your full name.';if(!/^\S+@\S+\.\S+$/.test(d.email||''))return'Enter a valid email address.';if(!d.title)return'Select your professional title.';if(!d.council)return'Select your registering body.';const id=(d.reg_id||'').toUpperCase().replace(/\s/g,'');if(!/^[A-Z0-9][A-Z0-9\/\-]{5,19}$/.test(id)||(id.match(/\d/g)||[]).length<4)return'Registration ID looks invalid. Use 6–20 characters with at least 4 digits, e.g. A12345 or CRR/2019/04567.';if(!(d.qual||'').trim())return'Enter your qualification.'}
  if(st==='c2'){if(!(d.area||'').trim())return'Enter your clinic or locality.';if(d.exp===undefined||d.exp===''||+d.exp<0)return'Enter years of experience.';if(!(d.spec||[]).length)return'Pick at least one specialisation.';if(!(d.modes||[]).length)return'Pick at least one session mode.'}
  return''}
function locate(cb){if(!navigator.geolocation){toast('Location is not available. Choose your city instead.');return}
  toast('Getting your location…');navigator.geolocation.getCurrentPosition(p=>{const la=p.coords.latitude,lo=p.coords.longitude;let best=META.cities[0],bd=1e9;META.cities.forEach(c=>{const d=km(la,lo,c[2],c[3]);if(d<bd){bd=d;best=c}});cb({lat:la,lng:lo},best[0],bd)},()=>toast('Could not get your location. Allow access, or choose your city.'),{timeout:10000})}

/* ---------- APP SHELL ---------- */
const UNAV=[['home','🏠','Home'],['find','📍','Find help'],['chats','💬','Messages'],['community','🫂','Community'],['wellness','🌿','Wellness'],['profile','👤','Profile']];
const CNAV=[['home','📊','Dashboard'],['clients','🧑‍🤝‍🧑','Clients'],['chats','💬','Messages'],['profile','👤','Profile']];
function enterApp(){U.view='home';go('home');pollUnread()}
async function go(v){U.view=v;stopPoll();endPractice();render(true);try{await (LOAD[v]&&LOAD[v]())}catch(e){toast(e.message)}if(U.view===v){render();window.scrollTo(0,0);if(v==='chats')startPoll()}}
function render(loading){if(!ME){renderAuth();return}
  const nav=ME.role==='user'?UNAV:CNAV;if(!nav.find(n=>n[0]===U.view))U.view='home';
  const badge=k=>k==='chats'&&V.unread?`<span class="unread">${V.unread}</span>`:'';
  const body=loading?'<div class="card muted">Loading…</div>':(ME.role==='user'?userView():counsellorView());
  app.innerHTML=`<div class="shell"><aside class="side"><div class="logo"><i>◐</i>Mindful Space</div>${nav.map(n=>`<button class="nav ${U.view===n[0]?'on':''}" data-act="go" data-v="${n[0]}"><span>${n[1]}</span>${n[2]}${badge(n[0])}</button>`).join('')}
<div style="flex:1"></div><button class="nav" data-act="theme"><span>🌓</span>Light / dark</button><button class="nav" data-act="logout"><span>↩</span>Sign out</button></aside><main class="main" id="main">${body}</main></div>
<nav class="bottom">${nav.slice(0,5).map(n=>`<button class="${U.view===n[0]?'on':''}" data-act="go" data-v="${n[0]}"><span>${n[1]}</span>${n[2].split(' ')[0]}</button>`).join('')}</nav>`;
  if(!loading&&U.view==='chats')paintChat()}
const LOAD={
  async home(){if(ME.role==='user'){[V.well,V.near,V.books]=await Promise.all([api('/wellness'),api('/counsellors?limit=3&sort=near'),api('/bookings')])}else V.dash=await api('/counsellor/dashboard')},
  async find(){V.helplines=META.helplines;await doSearch(true)},
  async chats(){V.th=await api('/threads');V.unread=V.th.unread;if(U.peer)await openConv(U.peer,true)},
  async community(){[V.fr,V.posts]=await Promise.all([api('/friends'),api('/posts')])},
  async wellness(){[V.well,V.journal]=await Promise.all([api('/wellness'),api('/journal')])},
  async profile(){V.books=await api('/bookings');if(ME.role==='counsellor')V.dash=null},
  async clients(){V.dash=await api('/counsellor/dashboard')}};
async function pollUnread(){try{if(!ME)return;const t=await api('/threads');if(t.unread!==V.unread){V.unread=t.unread;if(U.view!=='chats')render()}}catch(e){}setTimeout(pollUnread,20000)}

/* ---------- USER VIEWS ---------- */
function contactBtns(c){if(c.contact){const p=c.contact.phone;return `${p?`<a class="btn ghost sm" href="tel:+91${p}">📞 Call</a><a class="btn ghost sm" href="https://wa.me/91${p}" target="_blank" rel="noopener">WhatsApp</a>`:''}${c.contact.email?`<a class="btn ghost sm" href="mailto:${esc(c.contact.email)}">✉ Email</a>`:''}`}
  return c.demo?'<span class="small muted">Sample profile — contact details are hidden</span>':'<span class="small muted">Message in the app to get in touch</span>'}
function cCard(c,compact){const sBadge=c.demo?'<span class="badge demo">Sample profile</span>':'<span class="badge ok">✓ ID verified</span>';
  return `<div class="card cc" style="padding:16px">${av(c.name)}<div class="grow"><div class="row between wrap"><b>${esc(c.name)}</b><span class="price">${inr(c.fee)}<span class="small muted" style="font-family:var(--body);font-weight:500"> /50 min</span></span></div>
<div class="small muted">${esc(c.title)} · ${c.exp} yrs · ${esc(c.area||'')}, ${esc(c.city)}</div>
<div class="small" style="margin:6px 0">${c.reviews?`<span class="stars">★ ${c.rating}</span> <span class="muted">(${c.reviews})</span> · `:'<span class="muted">New · </span>'}${c.dist!==undefined?(c.dist<1?'<1':Math.round(c.dist))+' km away · ':''}${sBadge}</div>
<div>${c.spec.slice(0,compact?2:3).map(s=>`<span class="tag" style="margin-right:4px">${esc(s)}</span>`).join('')}</div>
${compact?'':`<div class="small muted" style="margin-top:8px">🗣 ${c.langs.join(', ')} · 🪪 ${esc(c.council)} · ${c.modes.join(' / ')}</div><p class="small" style="margin-top:6px">${esc(c.bio)}</p><div class="row wrap" style="margin-top:10px;gap:8px">${contactBtns(c)}</div>`}
<div class="row wrap" style="margin-top:10px;gap:8px"><button class="btn sm" data-act="book" data-id="${c.id}" ${c.avail?'':'disabled'}>${c.avail?'Book session':'Not available'}</button>${compact?'':`<button class="btn ghost sm" data-act="msg" data-id="${c.id}">Message</button>`}</div></div></div>`}
function ring(p){return `<div class="ring" style="--p:${p}"><div><span><b>${p}</b><span class="small">wellness</span></span></div></div>`}
function userView(){const v=U.view;
  if(v==='home'){const w=V.well,h=w.today,nb=(V.books.items||[]).find(b=>['confirmed','requested'].includes(b.status)&&b.date>=isoDay(0));
    const hr=new Date().getHours(),gr=hr<12?'Good morning':hr<17?'Good afternoon':'Good evening';
    const msg=w.score>=70?'A strong day. Keep it gentle.':w.score>=35?'You are on your way. One small practice helps.':'Start small: two minutes of breathing counts.';
    return `<div class="hello"><div class="row wrap" style="gap:24px">${ring(w.score)}<div class="grow" style="min-width:220px"><div class="small" style="opacity:.85">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</div><h2 style="margin:6px 0 8px">${gr}, ${esc(ME.nick)}</h2><p style="opacity:.92;margin-bottom:14px">${msg}</p><button class="btn" data-act="go" data-v="wellness">Start a practice</button></div></div>
<p class="small" style="opacity:.8;margin-top:14px">Your score is built from sleep, water, movement, calming practices and journaling — no daily questions.</p></div>
<div class="grid g3" style="margin-top:16px"><div class="card stat"><span class="muted small">Active streak</span><b>${w.streak} ${w.streak===1?'day':'days'}</b></div><div class="card stat"><span class="muted small">7-day average</span><b>${w.avg}</b></div><div class="card stat"><span class="muted small">Calm minutes today</span><b>${Math.round(h.practice_secs/60)}</b></div><div class="card stat"><span class="muted small">Journal entries</span><b>${w.journal_count}</b></div></div>
<div class="grid g2" style="margin-top:16px"><div class="card"><h3>Your week</h3><p class="small muted" style="margin:4px 0 14px">Daily wellness score</p><div class="bars">${w.series.map(x=>`<div><span class="${x.active?'':'e'}" style="height:${Math.max(5,x.score*1.1)}px"></span>${new Date(x.day+'T00:00').toLocaleDateString('en-IN',{weekday:'short'})}</div>`).join('')}</div></div>
<div class="card"><h3>Quick practices</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:10px;margin-top:12px">${PRACT.slice(0,4).map(p=>`<button class="pc" data-act="practice" data-k="${p[0]}"><span>${p[1]}</span><b>${p[2]}</b></button>`).join('')}</div>
${nb?`<div class="card" style="margin-top:14px;background:var(--surface2);box-shadow:none"><b>Next session</b><div class="small">${esc(nb.with_name)} · ${fmtDate(nb.date,nb.time)} · ${esc(nb.mode)} · ${nb.status==='requested'?'awaiting confirmation':'confirmed'}</div></div>`:''}</div></div>
<div class="row between" style="margin:26px 0 12px"><h3>Counsellors near ${esc(ME.city)}</h3><button class="btn ghost sm" data-act="go" data-v="find">See all</button></div><div class="grid g2">${V.near.items.map(c=>cCard(c,true)).join('')}</div>
<div class="card" style="margin-top:16px"><h3>Helplines in India</h3><div class="row wrap" style="margin-top:12px">${META.helplines.filter(h=>['14416','18005990019','112'].includes(h.phone)).map(h=>`<a class="btn ghost sm" href="tel:${h.phone}">📞 ${esc(h.name.split(' (')[0])}: ${esc(h.alt)}</a>`).join('')}</div></div>`}
  if(v==='find')return `<div class="top"><div><h2>Find help</h2><p class="muted small">Fees are per 50-minute session, in rupees.</p></div></div>
<div class="tabs"><button class="${U.tab==='counsellors'?'on':''}" data-act="tab" data-v="counsellors">Counsellors</button><button class="${U.tab==='helplines'?'on':''}" data-act="tab" data-v="helplines">Helplines & clinics</button></div>
${U.tab==='helplines'?helplinesHtml():`<div class="card"><div class="row wrap"><button class="btn teal sm" data-act="locate2">📍 Use my location</button><span class="small muted">Distances from ${esc(ME.city)}</span></div>
<div class="grid g3" style="margin-top:12px"><div><label class="f" style="margin-top:0">Search</label><input class="in" data-live="q" placeholder="Name, specialty, language, city…" value="${esc(U.q)}"></div>
<div><label class="f" style="margin-top:0">Location</label><select class="in" data-live="city"><option value="">All India</option>${META.cities.slice().sort((x,y)=>x[0].localeCompare(y[0])).map(c=>`<option ${U.city===c[0]?'selected':''} value="${c[0]}">${c[0]}, ${c[1]}</option>`).join('')}</select></div>
<div><label class="f" style="margin-top:0">Specialty</label><select class="in" data-live="spec"><option value="">Any</option>${META.specs.map(s=>`<option ${U.spec===s?'selected':''}>${s}</option>`).join('')}</select></div>
<div><label class="f" style="margin-top:0">Sort by</label><select class="in" data-live="sort">${[['near','Nearest'],['price','Fee: low to high'],['rating','Top rated'],['exp','Most experienced']].map(o=>`<option ${U.sort===o[0]?'selected':''} value="${o[0]}">${o[1]}</option>`).join('')}</select></div>
<div><label class="f" style="margin-top:0">Max fee: <b id="feeval">${inr(U.maxFee)}</b></label><input type="range" min="500" max="3000" step="100" value="${U.maxFee}" data-live="maxFee" style="width:100%"></div>
<div><label class="f" style="margin-top:0">Mode</label><select class="in" data-live="mode"><option value="">Any</option>${['Video','Audio','In-person'].map(s=>`<option ${U.mode===s?'selected':''}>${s}</option>`).join('')}</select></div></div></div><div id="results" style="margin-top:16px">${resultsHtml()}</div>`}`;
  if(v==='chats')return chatShell();
  if(v==='community'){const f=V.fr;return `<div class="top"><div><h2>Community</h2><p class="muted small">Connect under your nickname. Be kind — everyone here is figuring things out.</p></div></div>
${f.incoming.length?`<div class="card" style="margin-bottom:16px"><h3>Friend requests</h3><div style="display:grid;gap:10px;margin-top:10px">${f.incoming.map(p=>`<div class="row">${av(p.nick)}<div class="grow"><b>${esc(p.nick)}</b><div class="small muted">${esc(p.city||'')}</div></div><button class="btn sm" data-act="frresp" data-id="${p.id}" data-a="accept">Accept</button><button class="btn ghost sm" data-act="frresp" data-id="${p.id}" data-a="decline">Decline</button></div>`).join('')}</div></div>`:''}
<div class="grid g2"><div class="card"><h3>Your friends</h3><div style="margin-top:10px;display:grid;gap:10px">${f.friends.length?f.friends.map(p=>`<div class="row">${av(p.nick)}<div class="grow"><b>${esc(p.nick)}</b>${p.demo?' <span class="badge demo">Sample</span>':''}<div class="small muted">${esc(p.city||'')}</div></div><button class="btn ghost sm" data-act="openpeer" data-id="${p.id}">Chat</button></div>`).join(''):'<p class="muted small">No friends yet — add people from suggestions.</p>'}</div></div>
<div class="card"><h3>People you may know</h3><div style="margin-top:10px;display:grid;gap:10px">${f.suggestions.map(p=>`<div class="row">${av(p.nick)}<div class="grow"><b>${esc(p.nick)}</b>${p.demo?' <span class="badge demo">Sample</span>':''}<div class="small muted">${esc(p.city||'')}</div></div><button class="btn sm" data-act="addf" data-id="${p.id}">Add</button></div>`).join('')||'<p class="muted small">No suggestions right now.</p>'}${f.outgoing.length?`<p class="small muted">Waiting for: ${f.outgoing.map(p=>esc(p.nick)).join(', ')}</p>`:''}</div></div></div>
<div class="card" style="margin-top:16px"><h3>Share with the community</h3><textarea class="in" id="newpost" maxlength="600" style="margin-top:10px" placeholder="A win, a worry, a thought… posted as ${esc(ME.nick)}"></textarea><div class="row between wrap" style="margin-top:10px"><span class="small muted">Please don't share phone numbers, links or personal details.</span><button class="btn sm" data-act="post">Post</button></div></div>
<div style="display:grid;gap:12px;margin-top:16px">${V.posts.items.map(p=>`<div class="card"><div class="row">${av(p.nick)}<div class="grow"><b>${esc(p.nick)}</b> <span class="small muted">· ${esc(p.city||'')}</span>${p.demo?' <span class="badge demo">Sample</span>':''}</div><span class="tag">${esc(p.tag||'Post')}</span>${p.own?`<button class="btn ghost sm" data-act="delpost" data-id="${p.id}" aria-label="Delete post">🗑</button>`:''}</div><p style="margin:12px 0">${esc(p.body)}</p><button class="btn ${p.mine?'':'ghost'} sm" data-act="like" data-id="${p.id}">💜 Support ${p.support}</button></div>`).join('')}</div>`}
  if(v==='wellness'){const w=V.well,h=w.today;return `<div class="top"><div><h2>Wellness</h2><p class="muted small">Small daily habits add up. Your score updates as you go.</p></div></div>
<div class="grid g2"><div class="card"><h3>Calming practices</h3><p class="small muted" style="margin:4px 0 12px">Two minutes a day is enough to count.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px">${PRACT.map(p=>`<button class="pc" data-act="practice" data-k="${p[0]}"><span>${p[1]}</span><b>${p[2]}</b><small class="muted">${p[3]}</small></button>`).join('')}</div></div>
<div class="card"><h3>Today's habits</h3><label class="f">Water (glasses)</label><div class="row wrap" style="gap:6px">${[...Array(8)].map((_,i)=>`<button class="glass ${i<h.water?'on':''}" data-act="water" data-v="${i+1}" aria-label="${i+1} glasses"></button>`).join('')}</div>
<label class="f">Sleep last night: <b>${h.sleep||0} hrs</b></label><input type="range" min="0" max="12" step="0.5" value="${h.sleep||0}" data-habit="sleep" style="width:100%"><label class="f">Movement: <b>${h.move||0} min</b></label><input type="range" min="0" max="120" step="5" value="${h.move||0}" data-habit="move" style="width:100%"></div></div>
<div class="card" style="margin-top:16px"><h3>Journal</h3><p class="small muted" style="margin:4px 0 10px">Private to you. Write freely — a thought, a worry, a win.</p><textarea class="in" id="jtext" placeholder="What is on your mind?"></textarea><button class="btn sm" style="margin-top:10px" data-act="journal">Save entry</button>
<div style="margin-top:14px;display:grid;gap:10px">${V.journal.items.slice(0,8).map(j=>`<div class="card" style="box-shadow:none;background:var(--surface2)"><div class="row between"><span class="small muted">${new Date(j.ts*1000).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}</span><button class="btn ghost sm" data-act="deljournal" data-id="${j.id}" aria-label="Delete entry">🗑</button></div><p style="margin-top:4px;white-space:pre-wrap">${esc(j.body)}</p></div>`).join('')}</div></div>`}
  if(v==='profile'){const bk=V.books.items;return `<div class="top"><h2>Profile</h2></div><div class="grid g2"><div class="card"><div class="row">${av(ME.name,'lg')}<div><h3>${esc(ME.name)}</h3><div class="muted small">Shown as <b>${esc(ME.nick)}</b> in the community</div><div class="muted small">+91 ${esc(ME.phone)} ✓ verified</div></div></div>
<p class="small" style="margin-top:14px">📍 ${esc(ME.city)} · ${ME.age} yrs · ${esc(ME.gender||'')}</p><p class="small">🗣 ${ME.langs.join(', ')}</p><p class="small">Focus areas: ${ME.concerns.join(', ')||'—'}</p><p class="small">Emergency contact: ${ME.em_name||ME.em_phone?esc(ME.em_name||'')+' '+esc(ME.em_phone||''):'Not added'} <button class="btn ghost sm" data-act="editem">Edit</button></p>
<div class="row wrap" style="margin-top:14px"><button class="btn teal sm" data-act="locate2">📍 Update location</button><button class="btn ghost sm" data-act="theme">Light / dark</button><button class="btn rose sm" data-act="logout">Sign out</button></div>
<button class="btn ghost sm" style="margin-top:12px" data-act="delacct">Delete my account and data</button></div>
<div class="card"><h3>My sessions</h3><div style="margin-top:10px;display:grid;gap:12px">${bk.length?bk.map(b=>`<div><div class="row"><div class="grow"><b>${esc(b.with_name)}</b><div class="small muted">${fmtDate(b.date,b.time)} · ${esc(b.mode)} · ${inr(b.fee)}</div></div><span class="tag">${b.status}</span></div><div class="row wrap" style="margin-top:6px">${['requested','confirmed'].includes(b.status)?`<button class="btn ghost sm" data-act="cancelb" data-id="${b.id}">Cancel</button>`:''}${b.status==='completed'&&!b.rating?`<button class="btn sm" data-act="rate" data-id="${b.id}">Rate session</button>`:''}${b.rating?`<span class="small stars">★ ${b.rating}</span>`:''}<button class="btn ghost sm" data-act="openpeer" data-id="${b.with_id}">Message</button></div></div>`).join(''):'<p class="muted small">No sessions yet. Find a counsellor to book your first one.</p>'}</div></div></div>`}}
function helplinesHtml(){const q=U.hq.toLowerCase();const items=META.helplines.filter(h=>!q||(h.name+h.city+h.kind).toLowerCase().includes(q));
  return `<div class="card" style="margin-bottom:14px"><b>Verified public helplines and institutions</b><p class="small muted" style="margin-top:4px">Free or low-cost services run by government bodies, hospitals and non-profits. Hours can change — check before calling. In an emergency call 112.</p><input class="in" style="margin-top:10px" data-live="hq" placeholder="Search by name or city (e.g. Chennai)" value="${esc(U.hq)}"></div><div class="grid g2" id="hl">${hlCards(items)}</div>`}
function hlCards(items){return items.map(h=>`<div class="card"><div class="row between wrap"><b>${esc(h.name)}</b><span class="tag">${esc(h.kind)}</span></div><div class="small muted" style="margin:4px 0">📍 ${esc(h.city)} · ${esc(h.hours)}</div><a class="btn rose sm" href="tel:${h.phone}">📞 Call ${esc(h.alt)}</a></div>`).join('')||'<p class="muted">No matches.</p>'}
async function doSearch(first){const p=new URLSearchParams({limit:40,sort:U.sort,max_fee:U.maxFee});['q','city','spec','mode'].forEach(k=>U[k]&&p.set(k,U[k]));V.res=await api('/counsellors?'+p);if(!first){const r=$('#results');if(r)r.innerHTML=resultsHtml()}}
function resultsHtml(){const r=V.res;if(!r.items.length)return `<div class="card"><b>No counsellors match.</b><p class="muted small">Try All India, a higher fee limit, or fewer filters. Verified real counsellors appear here as they join.</p></div>`;
  return `<p class="small muted" style="margin-bottom:10px">${r.total} counsellor${r.total>1?'s':''} found</p><div class="grid g2">${r.items.map(c=>cCard(c)).join('')}</div>`}
let st;const debounced=fn=>{clearTimeout(st);st=setTimeout(()=>run(fn)(),300)};

/* ---------- CHAT ---------- */
function chatShell(){const th=V.th.items;
  if(!th.length&&!U.peer)return `<div class="top"><h2>Messages</h2></div><div class="card"><b>No conversations yet.</b><p class="muted small" style="margin:6px 0 12px">Message a counsellor or chat with a friend to start.</p><div class="row wrap"><button class="btn sm" data-act="go" data-v="find">Find counsellors</button>${ME.role==='user'?'<button class="btn ghost sm" data-act="go" data-v="community">Community</button>':''}</div></div>`;
  return `<div class="top"><h2>Messages</h2></div><div class="chat"><div class="card threads" id="tlist" style="padding:10px"></div><div class="card conv"><div class="row" style="padding:14px 18px;border-bottom:1px solid var(--line)" id="chead"></div><div class="msgs" id="msgs"></div><div class="send"><input class="in" id="msgin" placeholder="Type a message…" aria-label="Message" maxlength="2000"><button class="btn" data-act="send">Send</button></div></div></div>`}
function paintChat(){const tl=$('#tlist');if(!tl)return;const th=V.th.items.slice();if(U.peer&&V.conv&&!th.find(t=>t.peer===U.peer))th.unshift({peer:U.peer,name:V.conv.peer.name,last:'New conversation',unread:0});
  tl.innerHTML=th.map(t=>`<button class="th ${U.peer===t.peer?'on':''}" data-act="thread" data-id="${t.peer}">${av(t.name)}<div class="grow"><b>${esc(t.name)}</b>${t.demo?' <span class="badge demo">Sample</span>':''}<div class="small muted" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(t.last)}</div></div>${t.unread?`<span class="unread">${t.unread}</span>`:''}</button>`).join('');
  if(V.conv){$('#chead').innerHTML=`${av(V.conv.peer.name)}<div><b>${esc(V.conv.peer.name)}</b>${V.conv.peer.demo?' <span class="badge demo">Sample · replies are automated</span>':''}<div class="small muted">${esc(V.conv.peer.role==='counsellor'?'Counsellor':'Member')} · ${esc(V.conv.peer.city||'')}</div></div>`;paintMsgs()}
  else $('#msgs').innerHTML='<p class="muted small">Pick a conversation.</p>'}
function paintMsgs(){const m=$('#msgs');if(!m)return;const near=m.scrollHeight-m.scrollTop-m.clientHeight<80;m.innerHTML=V.conv.items.length?V.conv.items.map(x=>`<div class="m ${x.mine?'me':''}">${esc(x.body)}<small>${new Date(x.ts*1000).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</small></div>`).join(''):'<p class="muted small">Say hello 👋</p>';if(near||V.conv.fresh){m.scrollTop=m.scrollHeight;V.conv.fresh=false}}
async function openConv(id,quiet){const j=await api('/messages/'+id);V.conv={peer:j.peer,items:j.items,fresh:true};U.peer=id;U.lastId=j.items.length?j.items[j.items.length-1].id:0;if(!quiet)paintChat()}
function startPoll(){stopPoll();POLL=setInterval(run(async()=>{if(U.view!=='chats')return;const t=await api('/threads');V.th=t;V.unread=t.unread;if(U.peer&&V.conv){const j=await api(`/messages/${U.peer}?after=${U.lastId}`);if(j.items.length){V.conv.items.push(...j.items);U.lastId=j.items[j.items.length-1].id}}paintChat()}),3500)}
function stopPoll(){clearInterval(POLL);POLL=null}

/* ---------- COUNSELLOR VIEWS ---------- */
function sessRow(b,actions){return `<div class="row"><b style="width:84px;font-size:13px">${esc(b.date===isoDay(0)?'Today':fmtDate(b.date))}<br>${b.time}</b><div class="grow">${esc(b.with_name)}<div class="small muted">${esc(b.mode)} · ${(b.concerns||[]).slice(0,2).join(', ')}</div></div>${actions}</div>`}
function counsellorView(){const v=U.view,c=ME.counsellor;
  if(v==='home'){const d=V.dash;return `<div class="hello"><div class="small" style="opacity:.85">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</div><h2 style="margin:6px 0 10px">Welcome, ${esc(ME.name)}</h2>
<div class="row wrap"><span class="badge ${c.status==='verified'?'ok':'wait'}">${c.status==='verified'?'✓ ID verified':c.status==='rejected'?'ID not accepted':'⏳ ID verification pending'}</span><span class="small" style="opacity:.9">${esc(c.council)} · ${esc(c.reg_id)}</span></div>
<div class="row" style="margin-top:14px"><label class="row" style="cursor:pointer"><input type="checkbox" data-act="avail" ${c.avail?'checked':''}> <b>${c.avail?'Accepting new clients':'Not accepting new clients'}</b></label></div></div>
${c.status!=='verified'?`<div class="banner" style="margin-top:16px">Your profile is <b>hidden from search</b> until our team verifies your registration ID. You can set up your profile in the meantime.</div>`:''}
<div class="grid g3" style="margin-top:16px"><div class="card stat"><span class="muted small">Booked this month</span><b>${inr(d.earnings)}</b></div><div class="card stat"><span class="muted small">Sessions today</span><b>${d.today.length}</b></div><div class="card stat"><span class="muted small">Active clients</span><b>${d.clients.length}</b></div><div class="card stat"><span class="muted small">Completed</span><b>${d.completed}</b></div></div>
<div class="grid g2" style="margin-top:16px"><div class="card"><h3>Today</h3><div style="margin-top:12px;display:grid;gap:10px">${d.today.length?d.today.map(b=>sessRow(b,`<button class="btn ghost sm" data-act="bresp" data-id="${b.id}" data-a="complete">Mark done</button><button class="btn ghost sm" data-act="openpeer" data-id="${b.with_id}">Chat</button>`)).join(''):'<p class="muted small">No sessions today.</p>'}</div></div>
<div class="card"><h3>New requests</h3><div style="margin-top:12px;display:grid;gap:10px">${d.requests.length?d.requests.map(b=>sessRow(b,`<button class="btn sm" data-act="bresp" data-id="${b.id}" data-a="accept">Accept</button><button class="btn ghost sm" data-act="bresp" data-id="${b.id}" data-a="decline">Decline</button>`)).join(''):'<p class="muted small">No pending requests.</p>'}</div></div></div>
<div class="card" style="margin-top:16px"><h3>Upcoming</h3><div style="margin-top:12px;display:grid;gap:10px">${d.upcoming.length?d.upcoming.map(b=>sessRow(b,'')).join(''):'<p class="muted small">Nothing scheduled yet.</p>'}</div></div><p class="small muted" style="margin-top:12px">Clients appear under their nicknames. Payment is currently settled directly between you and the client.</p>`}
  if(v==='clients')return `<div class="top"><h2>Clients</h2></div><div class="grid g2">${V.dash.clients.length?V.dash.clients.map(x=>`<div class="card"><div class="row">${av(x.nick)}<div class="grow"><b>${esc(x.nick)}</b><div class="small muted">${x.concerns.join(', ')||'—'} · ${x.sessions} session${x.sessions>1?'s':''}</div></div><button class="btn ghost sm" data-act="openpeer" data-id="${x.id}">Message</button></div></div>`).join(''):'<div class="card"><b>No clients yet.</b><p class="muted small">Clients appear here after their first confirmed booking.</p></div>'}</div>`;
  if(v==='chats')return chatShell();
  if(v==='profile')return `<div class="top"><h2>Profile</h2></div><div class="grid g2"><div class="card"><div class="row">${av(ME.name,'lg')}<div><h3>${esc(ME.name)}</h3><div class="small muted">${esc(c.qual)} · ${c.exp} yrs</div><div class="small muted">+91 ${esc(ME.phone)} ✓ · ${esc(c.contact?.email||'')}</div></div></div>
<p class="small" style="margin-top:12px">📍 ${esc(c.area)}, ${esc(c.city)}</p><p class="small">🪪 ${esc(c.council)} — ${esc(c.reg_id)} <span class="badge ${c.status==='verified'?'ok':'wait'}">${c.status}</span></p><p class="small">🗣 ${c.langs.join(', ')} · ${c.modes.join(' / ')}</p><div style="margin-top:8px">${c.spec.map(s=>`<span class="tag" style="margin-right:4px">${esc(s)}</span>`).join('')}</div>
<label class="f">Bio</label><textarea class="in" id="cbio" maxlength="600">${esc(c.bio)}</textarea><button class="btn ghost sm" style="margin-top:8px" data-act="savebio">Save bio</button>
<div class="row wrap" style="margin-top:14px"><button class="btn teal sm" data-act="locate2">📍 Update location</button><button class="btn ghost sm" data-act="theme">Light / dark</button><button class="btn rose sm" data-act="logout">Sign out</button></div><button class="btn ghost sm" style="margin-top:12px" data-act="delacct">Delete my account and data</button></div>
<div class="card"><h3>Session fee</h3><p class="small muted" style="margin:4px 0 10px">Per 50-minute session, shown to clients in rupees.</p><div class="row"><input class="in" type="number" id="newfee" min="200" max="10000" step="50" value="${c.fee}"><button class="btn" data-act="savefee">Save</button></div>
<h3 style="margin-top:20px">Contact details</h3><p class="small muted" style="margin:4px 0 10px">Let clients reach you directly by phone, WhatsApp and email.</p><input class="in" id="cphone" inputmode="numeric" maxlength="10" placeholder="10-digit public number" value="${esc(c.contact?.phone||'')}"><label class="row small" style="margin-top:10px"><input type="checkbox" id="cshow" ${c.show_contact?'checked':''}> Show my contact details publicly</label><button class="btn ghost sm" style="margin-top:10px" data-act="savecontact">Save contact settings</button></div></div>`}

/* ---------- PRACTICES ---------- */
let PR={},AC=null,NS=null;
function endPractice(){if(!PR.kind)return;clearInterval(PR.t);if(NS){try{NS.stop()}catch(e){}NS=null}const s=Math.round((Date.now()-PR.t0)/1000),k=PR.kind;PR={};document.querySelectorAll('.modal.pr').forEach(m=>m.remove());if(s>=10&&ME&&ME.role==='user')api('/practice','POST',{kind:k,seconds:Math.min(s,3600)}).then(()=>{toast('Practice logged — nice work');if(['home','wellness'].includes(U.view))LOAD[U.view]().then(()=>render())}).catch(()=>{})}
function openPractice(k){endPractice();PR={kind:k,t0:Date.now()};const m=document.createElement('div');m.className='modal pr';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');
  const wrap=(t,inner)=>`<div class="card"><div class="row between"><h3>${t}</h3><button class="btn ghost sm" data-fin>Finish</button></div>${inner}</div>`;
  if(k==='breathing'){m.innerHTML=wrap('Breathe',`<p class="small muted" style="margin-top:6px">In through the nose for 4, out slowly for 6. Follow the circle.</p><div class="breath" id="bc">Get ready</div><p class="small muted" id="bt" style="text-align:center">0:00</p>`);
    let inh=true;const el=()=>m.querySelector('#bc');const cyc=()=>{const e=el();if(!e)return;e.textContent=inh?'Breathe in':'Breathe out';e.style.transitionDuration=inh?'4s':'6s';e.style.transform=inh?'scale(1.5)':'scale(1)';setTimeout(()=>{inh=!inh;if(PR.kind==='breathing')cyc()},inh?4000:6000)};setTimeout(cyc,600)}
  if(k==='grounding'){const S=['Name 5 things you can see.','Notice 4 things you can feel (your feet, your chair, your clothes).','Listen for 3 things you can hear.','Find 2 things you can smell.','Notice 1 thing you can taste.'];let i=0;m.innerHTML=wrap('Ground yourself',`<p class="step-q" id="gq">${S[0]}</p><p class="small muted" id="gp">Step 1 of 5 — take your time.</p><button class="btn" style="margin-top:14px" id="gn">Next</button>`);
    m.querySelector('#gn').onclick=()=>{i++;if(i>=S.length){m.querySelector('[data-fin]').click();return}m.querySelector('#gq').textContent=S[i];m.querySelector('#gp').textContent=`Step ${i+1} of 5 — take your time.`;if(i===S.length-1)m.querySelector('#gn').textContent='Done'}}
  if(k==='gratitude'){m.innerHTML=wrap('Three good things',`<p class="small muted" style="margin:6px 0">Small is fine — a good cup of tea counts.</p>${[1,2,3].map(n=>`<input class="in g3" style="margin-top:8px" maxlength="200" placeholder="Good thing ${n}">`).join('')}<button class="btn teal" style="margin-top:12px" id="gs">Save to journal</button>`);
    m.querySelector('#gs').onclick=run(async()=>{const t=[...m.querySelectorAll('.g3')].map(x=>x.value.trim()).filter(Boolean);if(!t.length){toast('Write at least one.');return}await api('/journal','POST',{body:'Gratitude:\n'+t.map(x=>'• '+x).join('\n')});m.querySelector('[data-fin]').click()})}
  if(k==='stretch'){const S=[['Neck release','Drop your right ear toward your right shoulder. Breathe slowly.'],['Shoulder rolls','Roll both shoulders backward in big, slow circles.'],['Chest opener','Clasp your hands behind you and gently lift.'],['Forward fold','Let your head and arms hang loose. Soften your knees.']];let i=0,left=20;
    m.innerHTML=wrap('Gentle stretch',`<p class="step-q" id="sq"></p><p class="muted" id="sd"></p><p class="stat"><b id="sl">20</b></p>`);const paint=()=>{m.querySelector('#sq').textContent=`${i+1}/4 · ${S[i][0]}`;m.querySelector('#sd').textContent=S[i][1];m.querySelector('#sl').textContent=left+'s'};paint();
    PR.t=setInterval(()=>{left--;if(left<=0){i++;left=20;if(i>=S.length){m.querySelector('[data-fin]').click();return}}paint()},1000)}
  if(k==='sound'){m.innerHTML=wrap('Calm sound',`<p class="small muted" style="margin:6px 0 14px">Soft rain-like noise to help you settle. Use headphones if you like.</p><button class="btn teal" id="sp">▶ Play</button><p class="small muted" id="st" style="margin-top:10px"></p>`);
    m.querySelector('#sp').onclick=()=>{if(NS){try{NS.stop()}catch(e){}NS=null;m.querySelector('#sp').textContent='▶ Play';return}try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();const len=AC.sampleRate*4,buf=AC.createBuffer(1,len,AC.sampleRate),d=buf.getChannelData(0);let last=0;for(let i=0;i<len;i++){const w=Math.random()*2-1;last=(last+.02*w)/1.02;d[i]=last*3.5}NS=AC.createBufferSource();NS.buffer=buf;NS.loop=true;const g=AC.createGain();g.gain.value=.5;NS.connect(g).connect(AC.destination);NS.start();m.querySelector('#sp').textContent='⏸ Stop'}catch(e){toast('Audio is not available on this device.')}};
    PR.t=setInterval(()=>{const s=Math.round((Date.now()-PR.t0)/1000);const x=m.querySelector('#st');if(x)x.textContent=`Time: ${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`},1000)}
  if(k==='breathing'){PR.t=setInterval(()=>{const s=Math.round((Date.now()-PR.t0)/1000);const x=m.querySelector('#bt');if(x)x.textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`},1000)}
  m.querySelector('[data-fin]').onclick=()=>endPractice();document.body.appendChild(m)}

/* ---------- BOOKING / RATING MODALS ---------- */
function openBook(id){const c=[...(V.res?.items||[]),...(V.near?.items||[])].find(x=>x.id===id);if(!c)return;let sel={d:0,t:null,m:c.modes[0],slots:[]};
  const m=document.createElement('div');m.className='modal';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');
  const loadSlots=run(async()=>{const j=await api(`/counsellors/${c.id}/slots?date=${isoDay(sel.d)}`);sel.slots=j.slots;sel.t=null;draw()});
  const draw=()=>{m.innerHTML=`<div class="card"><div class="row between"><h3>Book ${esc(c.name)}</h3><button class="btn ghost sm" data-x>✕</button></div><p class="small muted" style="margin:4px 0 8px">${esc(c.title)} · ${esc(c.area||'')}, ${esc(c.city)}</p>
<label class="f">Date</label><div>${[...Array(7)].map((_,i)=>`<button class="chip ${sel.d===i?'on':''}" data-d="${i}">${fmtDate(isoDay(i))}</button>`).join('')}</div>
<label class="f">Time (IST)</label><div>${sel.slots.map(x=>`<button class="chip ${sel.t===x.time?'on':''}" ${x.free?'':'disabled style="opacity:.4"'} data-s="${x.time}">${new Date('2000-01-01T'+x.time).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</button>`).join('')||'<span class="small muted">Loading…</span>'}</div>
<label class="f">Session type</label><div>${c.modes.map(x=>`<button class="chip ${sel.m===x?'on':''}" data-m="${x}">${x}</button>`).join('')}</div>
<div class="card" style="box-shadow:none;background:var(--surface2);margin-top:12px"><div class="row between"><b>Total</b><b class="price" style="color:var(--primary)">${inr(c.fee)}</b></div><p class="small muted" style="margin-top:6px">${c.demo?'Sample profile: this booking is confirmed automatically.':'Your request goes to the counsellor to confirm. You pay them directly at the session.'}</p></div>
<div class="err" id="berr"></div><button class="btn" style="width:100%" data-ok>Request booking</button></div>`;
    m.querySelector('[data-x]').onclick=()=>m.remove();m.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{sel.d=+b.dataset.d;sel.slots=[];draw();loadSlots()});m.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{sel.t=b.dataset.s;draw()});m.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>{sel.m=b.dataset.m;draw()});
    m.querySelector('[data-ok]').onclick=async()=>{if(!sel.t){m.querySelector('#berr').textContent='Pick a time slot.';return}try{const j=await api('/bookings','POST',{counsellor_id:c.id,date:isoDay(sel.d),time:sel.t,mode:sel.m});m.remove();toast(j.status==='confirmed'?'Session confirmed!':'Request sent. The counsellor will confirm shortly.');U.peer=c.id;go('profile')}catch(e){m.querySelector('#berr').textContent=e.message}}};
  m.addEventListener('click',e=>{if(e.target===m)m.remove()});draw();document.body.appendChild(m);loadSlots()}
function openRate(id){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="card"><h3>How was your session?</h3><div class="moods dark" style="margin:12px 0">${[1,2,3,4,5].map(n=>`<button data-n="${n}" aria-label="${n} stars">${'★'.repeat(n)}</button>`).join('')}</div><textarea class="in" id="rv" maxlength="400" placeholder="Optional note about your experience"></textarea><div class="row" style="margin-top:12px"><button class="btn ghost" data-x>Cancel</button></div></div>`;
  m.querySelector('[data-x]').onclick=()=>m.remove();m.querySelectorAll('[data-n]').forEach(b=>b.onclick=run(async()=>{await api(`/bookings/${id}/rate`,'POST',{rating:+b.dataset.n,review:m.querySelector('#rv').value});m.remove();toast('Thanks for your feedback');go('profile')}));document.body.appendChild(m)}

/* ---------- ACTIONS ---------- */
const acts={
  role(d){W.role=d.v;W.err='';renderAuth()},
  chip(d){const k=d.k,v=d.v;if(d.single==='1')W.d[k]=v;else{const l=W.d[k]=W.d[k]||[];const i=l.indexOf(v);if(i>=0)l.splice(i,1);else{if(k==='spec'&&l.length>=4){toast('Choose up to 4.');return}l.push(v)}}W.err='';renderAuth()},
  async sendotp(){if(!/^[6-9]\d{9}$/.test(W.phone)){aerr('Enter a valid 10-digit Indian mobile number (starts with 6, 7, 8 or 9).');return}W.busy=true;renderAuth();try{const j=await api('/auth/send-otp','POST',{phone:W.phone});W.dev=j.dev_otp||null;W.resendAt=Date.now()+30000;W.err='';W.step=1}catch(e){W.err=e.message}W.busy=false;renderAuth()},
  async verify(){if((W.otpIn||'').length!==6){aerr('Enter the 6-digit code.');return}W.busy=true;try{const j=await api('/auth/verify-otp','POST',{phone:W.phone,otp:W.otpIn,role:W.role});W.busy=false;W.otpIn='';if(j.exists){ME=j.me;enterApp();toast('Welcome back!');return}W.err='';W.step=2}catch(e){W.err=e.message}W.busy=false;renderAuth()},
  async resend(){try{const j=await api('/auth/send-otp','POST',{phone:W.phone});W.dev=j.dev_otp||null;W.resendAt=Date.now()+30000;W.err='';renderAuth();toast('A new code was sent.')}catch(e){aerr(e.message)}},
  back(){W.err='';W.step=Math.max(0,W.step-1);renderAuth()},
  next(){const e=validateStep();if(e){aerr(e);return}W.err='';W.step++;renderAuth()},
  locate(){locate((loc,city)=>{W.d.lat=loc.lat;W.d.lng=loc.lng;W.d.city=city;W.err='';renderAuth();toast('Location saved — nearest city: '+city)})},
  async finish(){const st=steps()[W.step],d=W.d;if(!d.consent){aerr(st==='u3'?'Please accept the note to continue.':'Please confirm the declaration.');return}
    if(st==='c3'){const f=+d.fee;if(!f||f<200||f>10000){aerr('Enter a fee between ₹200 and ₹10,000.');return}}
    W.busy=true;renderAuth();try{const j=await api('/auth/register','POST',{...d,role:W.role,phone:undefined});ME=j.me;W.busy=false;enterApp();toast(W.role==='user'?'Welcome, '+ME.nick+'!':'Registration received. Verification is pending.')}catch(e){W.busy=false;W.err=e.message;renderAuth()}},
  go(d){go(d.v)},
  theme(){const cur=document.documentElement.dataset.theme||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');const n=cur==='dark'?'light':'dark';document.documentElement.dataset.theme=n;try{localStorage.setItem('ms_theme',n)}catch(e){}},
  async logout(){await api('/auth/logout','POST').catch(()=>{});ME=null;stopPoll();W={role:'user',step:0,phone:'',otpIn:'',dev:null,resendAt:0,d:{},err:'',busy:false};renderAuth()},
  async delacct(){if(!confirm('Delete your account and all your data? This cannot be undone.'))return;await api('/me','DELETE');ME=null;renderAuth();toast('Your account was deleted.')},
  practice(d){openPractice(d.k)},
  tab(d){U.tab=d.v;render()},
  async locate2(){locate(async(loc,city,dist)=>{try{const j=await api('/me','PATCH',{city,lat:loc.lat,lng:loc.lng});ME=j.me;toast('Location updated — nearest city: '+city);if(U.view==='find')await doSearch(true);render()}catch(e){toast(e.message)}})},
  book(d){openBook(+d.id)},
  async msg(d){U.peer=+d.id;await go('chats')},
  async openpeer(d){U.peer=+d.id;await go('chats')},
  async thread(d){U.peer=+d.id;try{await openConv(U.peer)}catch(e){toast(e.message)}},
  async send(){const i=$('#msgin'),t=i.value.trim();if(!t||!U.peer)return;i.value='';try{const j=await api('/messages','POST',{to:U.peer,body:t});const r=await api(`/messages/${U.peer}?after=${U.lastId}`);V.conv.items.push(...r.items);if(r.items.length)U.lastId=r.items[r.items.length-1].id;V.conv.fresh=true;V.th=await api('/threads');paintChat();if(j.crisis)crisisModal()}catch(e){toast(e.message);i.value=t}$('#msgin')?.focus()},
  async addf(d){const j=await api('/friends/request','POST',{user_id:+d.id});toast(j.accepted?'Friend added':'Request sent');LOAD.community().then(render)},
  async frresp(d){await api('/friends/respond','POST',{user_id:+d.id,action:d.a});LOAD.community().then(render)},
  async like(d){await api(`/posts/${d.id}/support`,'POST');V.posts=await api('/posts');render()},
  async delpost(d){await api('/posts/'+d.id,'DELETE');V.posts=await api('/posts');render()},
  async post(){const t=$('#newpost').value.trim();if(!t){toast('Write something first.');return}const j=await api('/posts','POST',{body:t});V.posts=await api('/posts');render();toast('Posted');if(j.crisis)crisisModal()},
  async water(d){const h=V.well.today,n=h.water===+d.v?+d.v-1:+d.v;h.water=n;await saveHabits()},
  async journal(){const t=$('#jtext').value.trim();if(!t){toast('Write a few words first.');return}const j=await api('/journal','POST',{body:t});await LOAD.wellness();render();toast('Entry saved');if(j.crisis)crisisModal()},
  async deljournal(d){await api('/journal/'+d.id,'DELETE');await LOAD.wellness();render()},
  async cancelb(d){if(!confirm('Cancel this session?'))return;await api(`/bookings/${d.id}/cancel`,'POST');await LOAD.profile();render()},
  rate(d){openRate(+d.id)},
  editem(){const n=prompt('Emergency contact name',ME.em_name||'');if(n===null)return;const p=prompt('Emergency contact 10-digit number',ME.em_phone||'');if(p===null)return;run(async()=>{const j=await api('/me','PATCH',{em_name:n,em_phone:p});ME=j.me;render();toast('Saved')})()},
  async bresp(d){await api(`/bookings/${d.id}/respond`,'POST',{action:d.a});toast({accept:'Accepted',decline:'Declined',complete:'Marked complete'}[d.a]);V.dash=await api('/counsellor/dashboard');render()},
  async avail(d,el){const j=await api('/me','PATCH',{avail:el.checked});ME=j.me;render()},
  async savefee(){const j=await api('/me','PATCH',{fee:+$('#newfee').value});ME=j.me;render();toast('Fee updated')},
  async savebio(){const j=await api('/me','PATCH',{bio:$('#cbio').value});ME=j.me;toast('Bio saved')},
  async savecontact(){const j=await api('/me','PATCH',{contact_phone:$('#cphone').value,show_contact:$('#cshow').checked});ME=j.me;render();toast('Contact settings saved')}};
async function saveHabits(){const h=V.well.today;await api('/habits','PUT',{water:h.water,sleep:h.sleep,move:h.move});V.well=await api('/wellness');render()}
document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t||t.tagName==='INPUT')return;const f=acts[t.dataset.act];if(f)run(f)(t.dataset,t)});
document.addEventListener('change',e=>{const t=e.target;if(t.tagName==='INPUT'&&t.dataset.act==='avail')run(acts.avail)(t.dataset,t);if(t.dataset.live&&t.tagName==='SELECT'){U[t.dataset.live]=t.value;debounced(doSearch)}});
let hs;document.addEventListener('input',e=>{const t=e.target;
  if(t.dataset.live){const k=t.dataset.live;if(k==='hq'){U.hq=t.value;const h=$('#hl');if(h)h.innerHTML=hlCards(META.helplines.filter(x=>!U.hq||(x.name+x.city+x.kind).toLowerCase().includes(U.hq.toLowerCase())));return}
    if(t.tagName==='SELECT')return;U[k]=k==='maxFee'?+t.value:t.value;if(k==='maxFee')$('#feeval').textContent=inr(U.maxFee);debounced(doSearch)}
  if(t.dataset.habit){const h=V.well.today;h[t.dataset.habit]=+t.value;t.previousElementSibling.querySelector('b').textContent=t.dataset.habit==='sleep'?t.value+' hrs':t.value+' min';clearTimeout(hs);hs=setTimeout(run(saveHabits),700)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'){if(e.target.id==='msgin')run(acts.send)();if(e.target.id==='f_phone')run(acts.sendotp)();if(e.target.id==='f_otp')run(acts.verify)()}});
window.addEventListener('beforeunload',()=>{});

/* ---------- boot ---------- */
(async()=>{try{META=await api('/meta');try{const j=await api('/me');ME=j.me;enterApp()}catch(e){renderAuth()}}catch(e){app.innerHTML='<div style="padding:40px;font-family:sans-serif"><h2>Cannot reach the server</h2><p>Start the backend with <code>python app.py</code> and open <a href="/">http://127.0.0.1:5000</a>.</p></div>'}})();
